    pose proof (bv_unsigned_in_range _ s0) as S0R; change (bv_modulus 64) with (2^64)%Z in S0R;
    assert (BND : aceil <= lo /\ 6955312 <= TSD /\ TSD + 8 <= 7430144 /\ 7430144 <= CTX /\ CTX + 160 <= aceil
